window.SAQ_PAPER_QUESTIONS["2017-2-pah"]=[{"number":1,"title":"","stemText":"A 65 year old man has presented to hospital with shortness of breath.\nA chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the main pathology demonstrated on the chest x-ray. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 3 radiological abnormalities to support your diagnosis.\n(3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 differential diagnoses for this problem.\n(3 marks)"},{"id":"d","label":"Part D","prompt":"List and justify 5 further investigations you might perform to establish the diagnosis.\nInvestigation Justification"}],"propPages":["asset:imgff62cde71b6f92e7c8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Large right pleural effusion</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">homogenous opacification right middle and lower zone</div><div class=\"answer-line\">loss right hemidiaphragm</div><div class=\"answer-line\">rim of opacity around periphery of pleural cavity c/w fluid</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">parapneumonic effusion</div><div class=\"answer-line\">malignancy</div><div class=\"answer-line\">PE</div><div class=\"answer-line\">Hydrothorax from massive ascites</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Investigation</td><td>Justification</td></tr><tr><td>Pleural fluid culture</td><td>Identify organism and target antibiotic Rx</td></tr><tr><td>Pleural fluid biochem – LDH, protein</td><td>Will differentiate transudate vs exudate</td></tr><tr><td colspan=\"2\">(Light’s criteria)</td></tr><tr><td>Pleural fluid cytology</td><td>Will identify malignancy</td></tr><tr><td>CT scan</td><td>Look for malignancy, esp after effusion</td></tr><tr><td colspan=\"2\">drained</td></tr><tr><td>CTPA</td><td>Diagnose PE</td></tr><tr><td colspan=\"2\">Many others may be acceptable as long as they are reasonably justifiable</td></tr><tr><td colspan=\"2\">Justification must be good</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 33 year old woman has presented to the ED with a severe headache.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your history that would support the diagnosis of migraine.\n(4 marks) You have assessed the patient to be suffering from a migraine."},{"id":"b","label":"Part B","prompt":"List 5 drugs, each from a different class, that can be used as first line treatment for\nmigraine. Include doses. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 3 drugs that can be used for prophylaxis in recurrent migraine.\n(3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">unilateral throbbing headache</div><div class=\"answer-line\">presence of visual aura</div><div class=\"answer-line\">past Hx migraine</div><div class=\"answer-line\">gradual onset</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Paracetamol 1g po</td></tr><tr><td>Ibuprofen</td><td>400mg po</td></tr><tr><td>Sumatriptan</td><td>6mg sc</td></tr><tr><td>Metoclopramide</td><td>10mg po/IV/IM</td></tr><tr><td colspan=\"2\">Chlorpromazine 25mg IV</td></tr><tr><td>Dihydroergotamine</td><td>0.25 – 1mg IV</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Amitriptyline</div><div class=\"answer-line\">Propranolol</div><div class=\"answer-line\">Pizotifen</div><div class=\"answer-line\">Valproate</div><div class=\"answer-line\">Topiramate</div><div class=\"answer-line\">Verapamil</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 45 year old man has been transferred to your ED after a scuba diving trip. He complained of feeling unwell after ascending from a deep dive. You are worried he might have decompression sickness.","parts":[{"id":"a","label":"Part A","prompt":"List 5 clinical features of decompression sickness.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 other diving related pathologies that might present shortly after rapid ascent.\n(5 marks) After a full assessment, you have decided that the patient has significant decompression sickness.\nHis vital signs are:\n\nGCS\nE4 V4 M6 Pulse 105 /min\n\nBP\n110/65 mmHg O2 sats 93% room air"},{"id":"c","label":"Part C","prompt":"List 3 main features of your management.\n(3 marks) 1)________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pain – muscles / joints “the bends”</div><div class=\"answer-line\">Lymphedema</div><div class=\"answer-line\">Pulmonary DCS – cough, haemoptysis, dyspnea, chest pain</div><div class=\"answer-line\">Neurological DCS – spinal cord syndromes or pretty much any neurological symptom</div><div class=\"answer-line\">Vestibular symptoms – vertigo, hearing loss</div><div class=\"answer-line\">Fatigue</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pneumothorax/mediastinum</div><div class=\"answer-line\">Middle ear pathologies</div><div class=\"answer-line\">Sinus pain</div><div class=\"answer-line\">Arterial gas embolism esp cerebral</div><div class=\"answer-line\">Tooth pain</div><div class=\"answer-line\">Abdominal cramps</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">100% O2</div><div class=\"answer-line\">IV fluids – 1L N/S</div><div class=\"answer-line\">Organize hyperbaric treatment</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 78 year old woman has presented to the ED after a 3 day history of lethargy. She has been febrile and has complained of dysuria and right flank pain. Her past medical history includes type 2 diabetes mellitus, congestive cardiac failure and hypertension. Her blood results are given in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give explanations for the following abnormalities. Include formulae where asked:\n\nHCO3 6\n(3 marks) Formula: __________________________________________________________________________\n\nGlucose 66.6\n(1 mark)\n\nNa 119\n(2 marks) Formula: __________________________________________________________________________\n\nK 8.4\n(1 mark)\n\nUrea 15.7 and creatinine 298\n(2 marks) Formula: __________________________________________________________________________ On examination, the patient has the following vital signs:\n\nGCS\nE3 V4 M6 Pulse 120 /min\n\nBP\n95/55 mmHg\n\nTemp\n38.9 degrees\n\nRR\n/min O2 sats 99% room air Her abdomen is soft with right renal angle tenderness. ECG shows sinus tachycardia with tall peaked T waves and broad QRS complexes."},{"id":"b","label":"Part B","prompt":"State 6 steps in your management of this patient.\n(6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":["asset:img3c807eee5c32807915"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/15</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">HCO3 – high anion gap metabolic acidosis due to renal failure, probably also lactate and</div><div class=\"answer-line\">ketones</div><div class=\"answer-line\">Formula: anion gap = Na – (HCO3 + Cl)</div><div class=\"answer-line\">Glucose – due to HHS, as a result of poor glycaemic control in the context of sepsis</div><div class=\"answer-line\">Na – dilutional due to hyperglycaemia, corrects to 139 – normal</div><div class=\"answer-line\">Formula: corrected Na = Na + (glucose-5)/3</div><div class=\"answer-line\">K – elevated due to intracellular shift from likely acidaemia, and also renal failure</div><div class=\"answer-line\">Urea,creat – renal failure, intrinsic as ratio &lt;100, probably due to ATN and maybe</div><div class=\"answer-line\">pyleonephritis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ca gluconate 30ml 10%</div><div class=\"answer-line\">HCO3 50mmol (to treat hyper K)</div><div class=\"answer-line\">fluid bolus – 500-1000mL N/S aiming for BP &gt;100mmHg and good perfusion</div><div class=\"answer-line\">insulin infusion – start at 5U/hr</div><div class=\"answer-line\">IV abs – eg ceftriaxone 1g</div><div class=\"answer-line\">Also accept other hyperK Rx – salbutamol 5mg neb, resonium 30g po</div><div class=\"answer-line\">DVT prophylaxis – any standard regime is fine eg heparin / dalteparin</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 72 year old man has been brought to the ED after a syncopal episode.\nHis ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your interpretation of the ECG. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 features of the ECG that support your interpretation.\n(3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 possible causes of this problem. (4 marks)\nOn examination, the patient looks pale and sweaty.\nHis vital signs are:\n\nGCS\nE3 V4 M6\n\nBP\n70/40 mmHg\n\nRR\n/min O2 saturations 99% room air You have decided to initiate electrical pacing."},{"id":"d","label":"Part D","prompt":"State 5 steps in the successful implementation of electrical pacing.\n(5 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) _______________________________________________________________________________ 5) _______________________________________________________________________________"}],"propPages":["asset:imgc7935d7de016c670b6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/14</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Complete heart block</div><div class=\"answer-line\">AV nodal escape</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">AV dissociation</div><div class=\"answer-line\">Narrow complex QRS</div><div class=\"answer-line\">P rate approx. 80, QRS rate approx. 35</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hyperkalaemia</div><div class=\"answer-line\">Cardiac ischaemia</div><div class=\"answer-line\">Drugs eg beta-blockers</div><div class=\"answer-line\">Cardiac fibrosis</div><div class=\"answer-line\">Infiltrative diseases</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Explanation/consent</div><div class=\"answer-line\">Pad position – AP or anterior apex/base</div><div class=\"answer-line\">Sedation eg midazolam 1mg boluses</div><div class=\"answer-line\">Select energy level – titrate to capture</div><div class=\"answer-line\">Ensure electrical and mechanical capture</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 4 year old boy has been brought to your regional ED after being found at the bottom of a pool. He was found to be in a state of Pulseless Electrical Activity on the arrival of the ambulance crew. The ambulance crew were able to achieve return of spontaneous circulation. As part of the resuscitative effort, the child has been intubated.","parts":[{"id":"a","label":"Part A","prompt":"List 5 features of your assessment that would be relevant in determining the likelihood of intact neurological survival. (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 important possible clinical complications of this presentation that may require active management. (5 marks) The patient requires road transfer to your nearest tertiary centre."},{"id":"c","label":"Part C","prompt":"List 5 medications you might need during the transfer."},{"id":"d","label":"Part D","prompt":"List 5 essential pieces of equipment you will need for the transfer.\n(5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>14/20</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Duration of immersion</div><div class=\"answer-line\">Duration of ALS</div><div class=\"answer-line\">Initial rhythm</div><div class=\"answer-line\">Delay to BLS</div><div class=\"answer-line\">Need for circulatory support post ROSC</div><div class=\"answer-line\">GCS on arrival to ED</div><div class=\"answer-line\">Many others acceptable also</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pulmonary: Chemical Pneumonitis, Atelectasis from surfactant loss, ARDS</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Hyponatremia</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Cerebral: Seizures, Hypoxia, Persistent coma</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Adrenaline</div><div class=\"answer-line\">Paralysis – most agents acceptable</div><div class=\"answer-line\">Sedation of some sort</div><div class=\"answer-line\">Glucose eg 5% dextrose</div><div class=\"answer-line\">Normal saline</div><div class=\"answer-line\">Midazolam</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">BVM</div><div class=\"answer-line\">Ventilator</div><div class=\"answer-line\">Monitor</div><div class=\"answer-line\">Airway equipment in case of extubation</div><div class=\"answer-line\">O2 cylinders</div><div class=\"answer-line\">Suction</div><div class=\"answer-line\">Many others OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 20 year old man has been punched to the face during an altercation at a bar. He is complaining of a painful, swollen face. A coronal slice from his CT scan is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 radiological abnormalities.\n(3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ You are about to examine the patient."},{"id":"b","label":"Part B","prompt":"Complete the table. Give 5 important components of your examination. Justify each\ncomponent by listing a"}],"propPages":["asset:img394cb35a1740ef4f73"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Inferiorly displaced left orbital floor fracture</div><div class=\"answer-line\">Fluid (blood) in left maxillary sinus</div><div class=\"answer-line\">Inferior rectus is displaced in to fracture segment – will accept entrapped</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Examination component</td><td>Pathology</td></tr><tr><td>Visual acuity</td><td>Any significant eye pathology eg vitreous</td></tr><tr><td colspan=\"2\">haemorrhage</td></tr><tr><td>Eye movements – diplopia on upward gaze</td><td>Inferior rectus entrapment</td></tr><tr><td>Sensation left midface</td><td>Infra-orbital nerve injury</td></tr><tr><td>Nasal septum inspection</td><td>Septal haematoma</td></tr><tr><td>Cervical spine assessment</td><td>C-spine fracture</td></tr><tr><td>Neurological assessment</td><td>Intracranial haemorrhage</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 7 year old boy has injured his left arm after falling off a swing in the playground.\nHis x-rays (lateral and AP) are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 radiological abnormalities on the x-ray. (3 marks)"},{"id":"b","label":"Part B","prompt":"Classify the injury. (1 mark)\nThe child weighs 25 kilograms."},{"id":"c","label":"Part C","prompt":"List 3 different options for analgesia, including doses. (3 marks)\nYou intend to examine the patient’s arm for neurological injury."},{"id":"d","label":"Part D","prompt":"In the table below, list one sensory and motor function that you will assess for each of the nerves listed. (6 marks) Nerve Motor function Sensory function Radial nerve Median nerve Ulnar nerve"}],"propPages":["asset:imga359540f7986cdb504","asset:imga9382ff9497c0e581e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Proximal ulna fracture</div><div class=\"answer-line\">Dislocated radial head (anterior)</div><div class=\"answer-line\">Enlarged anterior fat pad</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Monteggia fracture / dislocation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Fentanyl – IN 35mcg (approx.), IV 25mcg boluses (approx.)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Must have one parenteral opiate though</div><div class=\"answer-line\">4.</div><div class=\"answer-line\">Nerve</div><div class=\"answer-line\">Motor</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Dorsum 1st webspace</td><td></td></tr><tr><td>radial</td><td>Wrist extension, finger extension</td></tr><tr><td>median</td><td>LOAF muscles – lateral 2 Lateral palm, including lateral half of</td></tr><tr><td>lumbricals, opponens policis,</td><td>ring finger</td></tr><tr><td>abductor pollicis brevis, flexor</td><td></td></tr><tr><td>pollicus brevis</td><td></td></tr><tr><td>ulnar</td><td>interossei Medial palm including medial half of ring</td></tr><tr><td>finger</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are the consultant in charge of a tertiary ED on a Saturday evening. You have been notified by the ambulance of a bomb explosion at a local sporting stadium. The ambulance officer in charge of the scene has rung to say that you will receive an unknown number of patients, possibly several hundred. You have activated the hospital’s disaster notification.","parts":[{"id":"a","label":"Part A","prompt":"List 8 important aspects of your preparation of the ED.\n(8 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________ 7) ________________________________________________________________________________ 8) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 6 problems that you are likely to encounter in the next 24 hours. (6 marks)\n1)________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/14</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Locations</div><div class=\"answer-line\">Clear beds – admit any suitable patients to wards</div><div class=\"answer-line\">Move stable, ambulant patients to alternate area</div><div class=\"answer-line\">Decant Resus areas</div><div class=\"answer-line\">Notify waiting room of anticipated surge/mass casualty and offer alternate treatment</div><div class=\"answer-line\">options</div><div class=\"answer-line\">Establish specific triage area</div><div class=\"answer-line\">Personnel</div><div class=\"answer-line\">All ED staff to stay on shift</div><div class=\"answer-line\">Call-in all available staff</div><div class=\"answer-line\">Establish teams</div><div class=\"answer-line\">Notify surgical/orthopaedic teams</div><div class=\"answer-line\">Ensure radiology</div><div class=\"answer-line\">Equipment</div><div class=\"answer-line\">Ensure adequate stocks of:</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Splints/Plaster</div><div class=\"answer-line\">Ventilators</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lack of access to radiology</div><div class=\"answer-line\">Staff fatigue</div><div class=\"answer-line\">Access to OT</div><div class=\"answer-line\">ICU bed availability</div><div class=\"answer-line\">Exhausted blood bank supply</div><div class=\"answer-line\">Stock shortages – splints, drugs, antibiotics</div><div class=\"answer-line\">Some others</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 50 year old farmer has been run over by a tractor.\nHe has severe pelvic pain.\nHis vital signs are:\n\nGCS 13\nE3 V4 M6 Pulse 140 /min\n\nBP\n70/30 mmHg O2 Sats 99% room air His CXR is normal. His pelvic x-ray is given in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the x-ray.\n(3 marks)"},{"id":"b","label":"Part B","prompt":"Classify the injury pattern using a recognized system. (1 mark)"},{"id":"c","label":"Part C","prompt":"State the immediate intervention you would perform. Include the endpoint for your intervention. (2 marks) Intervention: End-point:"},{"id":"d","label":"Part D","prompt":"List 3 injuries that are commonly associated with this type of pelvic injury. For each, list the clinical findings that would support its presence. (6 marks) Injury Supportive clinical findings As part of your assessment a FAST scan is performed. The image obtained is provided in the PROPS BOOKLET."},{"id":"e","label":"Part E","prompt":"State your conclusion from the image provided. Include the clinical implication of this finding. (2 marks) Conclusion Clinical implication You have initiated a massive transfusion protocol (MTP) -based approach for your resuscitation."},{"id":"f","label":"Part F","prompt":"List 4 key laboratory end-points you will target to guide your MTP resuscitation.\n(4 marks)"},{"id":"g","label":"Part G","prompt":"List 5 complications specific to massive volume transfusion.\n(5 marks)"}],"propPages":["asset:imgbdcd6ebf2fee764930","asset:img8795fbd341470ddf07","asset:imga655364b3ae592d4ee","asset:imgb132a9a8aaae4d1d97","asset:img8e72fdc30b2bc5f38e","asset:img464e53640b73f90d29"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>16/23</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pubic diastasis</div><div class=\"answer-line\">Widened R Sacro-Iliac Joint</div><div class=\"answer-line\">Widened L Sacro-Iliac Joint</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Injury classification: APC 3 (Rt) ; technically bilat but Rt-side distracted</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pelvic binder application</div><div class=\"answer-line\">End-point – closure of diastasis</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Sacral plexus – LL neurology – anything really but motor/reflexes as best sign</td><td>Bladder – Haematuria</td></tr><tr><td>Bowel – PR bleeding/bony fragment on PR exam</td><td>Urethra – perineal haematoma, blood at meatus, inability to pass urine</td></tr><tr><td>Major vessels – internal iliacs or other pelvic vessels – haemorrhagic shock</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Finding: negative Morrison’s/RUQ view</div><div class=\"answer-line\">Clinical implications – Laparotomy unlikely to be of any direct benefit – needs management</div><div class=\"answer-line\">of pelvic bleeding</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Platelets &gt;50</div><div class=\"answer-line\">Fibrinogen &gt;1.0</div><div class=\"answer-line\">Ionised Ca &gt;1.1</div><div class=\"answer-line\">INR &lt;1.5</div><div class=\"answer-line\">pH</div><div class=\"answer-line\">&lt;7.2</div></section><section class=\"answer-part\"><h5>Part G</h5><div class=\"answer-line\">Coagulopathy</div><div class=\"answer-line\">Hypocalcaemia</div><div class=\"answer-line\">Volume Overload</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Metabolic alkalosis</div><div class=\"answer-line\">Hyperkalaemia</div><div class=\"answer-line\">TRALI</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 70 year old female is brought to ED with acute breathlessness. Your provisional diagnosis is of acute pulmonary oedema (APO).","parts":[{"id":"a","label":"Part A","prompt":"List 4 findings on clinical examination that would support a diagnosis of APO. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 possible precipitants for this patient’s pulmonary oedema.\n(4 marks) The patient does not require immediate intubation."},{"id":"c","label":"Part C","prompt":"List two specific ED treatments you could employ to manage this patient’s pulmonary\n• edema. For each, list your initial treatment prescription and your CLINICAL end-points.\nTreatment 1\nClinical end-point\nTreatment 2\nClinical end-point"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Raised JVP</div><div class=\"answer-line\">Hepatomegaly</div><div class=\"answer-line\">Tachycardia</div><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Hypoxia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Cardiac Ischaemia</div><div class=\"answer-line\">Renal failure</div><div class=\"answer-line\">Non-compliance with fluid restriction / medications</div><div class=\"answer-line\">Intercurrent illness</div><div class=\"answer-line\">Stress (Ie takotsubo cardiomyopathy)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>5-100mcg/min (IV infusion 50mg in 50ml)</td><td>Target end points – reduction in pre-load – systolic BP reduction to something</td></tr><tr><td>reasonable ie 30% reduction or Clinical end point – decreased work of breathing</td><td>or subjective dyspnoea, decreased tachypnoea, improved oxygenation etc</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"The ambulance service has brought a 60 year old man to the ED with abnormal behaviour. They were called by motorists who reported him running amongst traffic.","parts":[{"id":"a","label":"Part A","prompt":"List 6 features on your history that would suggest an organic cause for the patient’s\npresentation. (6 marks) Your initial assessment suggests an organic cause for the patient’s abnormal behaviour."},{"id":"b","label":"Part B","prompt":"List 3 investigations you would perform (with rationale) to investigate for possible organic precipitants. (3 marks) Investigation Rationale The patient required manual restraint whilst attempting to leave. A member of nursing staff has been bitten on the finger, drawing blood."},{"id":"c","label":"Part C","prompt":"State 6 key principles of the ED management of this incident. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/15</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Drug Use</div><div class=\"answer-line\">Recent trauma</div><div class=\"answer-line\">Immunosuppression</div><div class=\"answer-line\">Abrupt onset</div><div class=\"answer-line\">Hx malignancy</div><div class=\"answer-line\">Weight loss</div><div class=\"answer-line\">Visual hallucinations</div><div class=\"answer-line\">(Many others)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>BSL</td><td>exclude hypo/hyperglycaemia as cause of agitation</td></tr><tr><td>CT head</td><td>exclude mass lesion/bleed</td></tr><tr><td>CXR</td><td>exclude pneumonia</td></tr><tr><td>Urine Drug Screen</td><td>look for substance induced MH disturbance</td></tr><tr><td>Thyroid Function tests</td><td>exclude thyrotoxicosis</td></tr><tr><td>Electrolytes</td><td>exclude renal injury / hyponatremia as cause</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">First aid – copious wound irrigation</div><div class=\"answer-line\">Remove from clinical duties</div><div class=\"answer-line\">Report to infection control/similar</div><div class=\"answer-line\">Test source and victim for HepB/HepC/HIV</div><div class=\"answer-line\">HepB immunisation (passive) if victim not immunised</div><div class=\"answer-line\">Antibiotics if suspect deep structures involved (Augmentin) – human bite</div><div class=\"answer-line\">Incident report completed for QI / review restraint procedures</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 5 week old boy has been brought to ED with vomiting and lethargy.\nA venous blood gas had been obtained. The result is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List the acid-base abnormalities present. Include your calculations where relevant. (5 marks)"},{"id":"b","label":"Part B","prompt":"State your most likely diagnosis, and state how you would confirm this on investigation. (2 marks) You estimate the patient to be 10% dehydrated. He weighs 5 kg."},{"id":"c","label":"Part C","prompt":"State 3 important aspects of your fluid management of this patient.\n(3 marks) Fluid type Maintenance rate Deficit replacement rate (over 24 hrs)"}],"propPages":["asset:img984590b1b831afeb5c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">3. 0.9% saline + 5% dextrose (or other safe alternative)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">2. Pyloric stenosis – confirmed by USS identification of hypertrophic pylorus</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">3. 0.9% saline + 5% dextrose (or other safe alternative)</div><div class=\"answer-line\">Maintenance is 20mls/hr</div><div class=\"answer-line\">Deficit is 500mls over 24 hrs = 21mls/hr</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 75 year old man has been referred to the ED by his GP with symptomatic anaemia.","parts":[{"id":"a","label":"Part A","prompt":"List 5 key differential diagnoses. For each differential diagnosis, state one important\nsupportive finding on FBE/blood film and one other key investigative finding that would support that diagnosis. (15 marks) Differential diagnosis FBE / blood film finding Other key investigation finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>11/15</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Investigation Finding</td><td></td></tr><tr><td>(can be on blood film)</td><td></td></tr><tr><td>Iron Deficiency or</td><td>Microcytosis/ Iron studies</td></tr><tr><td>anything similar</td><td>Other cell lines Reticulocytosis</td></tr><tr><td>(ie GIT</td><td>preserved</td></tr><tr><td>bleed/bowel</td><td></td></tr><tr><td>malignancy</td><td></td></tr><tr><td>Leukaemia</td><td>Other cell lines Blasts on film</td></tr><tr><td>involved –</td><td></td></tr><tr><td>pancytopaenia</td><td></td></tr><tr><td>Aplastic Anaemia/</td><td>Pancytopaenia Blasts not present/ no</td></tr><tr><td>myelofibrosis</td><td>reticulocytosis</td></tr><tr><td>CRF/EPO</td><td>Normocytosis/ CRF on U&amp;Es</td></tr><tr><td>deficiency</td><td>Other cell lines</td></tr><tr><td>normal</td><td></td></tr><tr><td>Vitamin</td><td>Macrocytosis Deficiency B12/Folate</td></tr><tr><td>Deficiency –</td><td>levels</td></tr><tr><td>B12/Folate</td><td></td></tr><tr><td>Haemolysis</td><td>Isolated anaemia Schistocytes,</td></tr><tr><td>unconjugated</td><td></td></tr><tr><td>hyperbilirubinaemia,</td><td></td></tr><tr><td>raised LDH, low</td><td></td></tr><tr><td>haptoglobin</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 7 year old girl has been brought to the ED with an exacerbation of asthma.","parts":[{"id":"a","label":"Part A","prompt":"List 4 clinical or investigative findings that would indicate an imminent need for\nintubation. (4 marks) The child is experiencing a life-threatening asthma attack. She will require intubation as part of her\n• ngoing management.\nHer vital signs are:\n\nGCS\nE3 V5 M6 Pulse 175 /min\n\nBP\n90/55 mmHg\n\nRR\n/min O2 sats 89% 15L O2 via non-rebreather mask"},{"id":"b","label":"Part B","prompt":"List 4 difficulties you anticipate during this patient’s intubation and ventilation. Give your strategy to manage each difficulty. (8 marks) Difficulty Management strategy"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Drowsiness</td></tr><tr><td>-</td><td>Collapse</td></tr><tr><td>-</td><td>Refractory Hypoxia</td></tr><tr><td>-</td><td>Bradycardia</td></tr><tr><td>-</td><td>Apnoea</td></tr><tr><td>-</td><td>Silent Chest</td></tr><tr><td>-</td><td>Poor resp effort</td></tr><tr><td>-</td><td>Investigative findings –relative hypercapnoea</td></tr><tr><td colspan=\"2\">There are likely many more….</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">strategy, avoid apnoea, induce sitting up</div><div class=\"answer-line\">High-pressure ventilation: manual ventilation, increased pressure limits to maintain</div><div class=\"answer-line\">PPlat &lt;30cmH20</div><div class=\"answer-line\">Cardiovascular collapse with raised thoracic pressures: Fluid bolus, start adrenaline</div><div class=\"answer-line\">Dynamic Hyperinflation: Slow bag – 4-6/min, disconnect from ventilator</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"You have been called to see a patient in your department who is awaiting orthopaedic admission for a complex lower leg fracture requiring operative fixation. Your registrar has placed the patient in an above knee cast which has been split laterally. The nurses are worried that the patient has increasing pain and distress. The orthopaedic registrar has been repeatedly delayed due to theatre cases. The initial x-ray (prior to immobilisation) is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 6 radiological abnormalities on this image.\n(6 marks)"},{"id":"b","label":"Part B","prompt":"Apart from increasing pain, list 4 features of your examination that would suggest the development of compartment syndrome in the leg. (4 marks) Your assessment is highly concerning for compartment syndrome. The orthopaedic registrar is unable to leave the operating theatre for at least another hour."},{"id":"c","label":"Part C","prompt":"State 4 immediate management priorities in this situation.\n(4 marks)"}],"propPages":["asset:imgc1fa25ee7876f64d9e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/14</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Proximal fracture tibia minimally displaced</td></tr><tr><td colspan=\"2\">Proximal fibula fracture</td></tr><tr><td colspan=\"2\">Mid-shaft tibia+fibula fractures</td></tr><tr><td>-</td><td>Comminuted</td></tr><tr><td>-</td><td>Laterally angulated</td></tr><tr><td>-</td><td>Slightly shortened</td></tr><tr><td>-</td><td>Mildly laterally displaced</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Altered sensation below injury</div><div class=\"answer-line\">Pale foot</div><div class=\"answer-line\">Loss DP pulse</div><div class=\"answer-line\">Tense muscle compartments</div><div class=\"answer-line\">Cool foot</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Elevation</div><div class=\"answer-line\">Remove any external compression (splints/slabs/bandages)</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Immediate orthopaedic attendance for fasciotomy</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"You are the director of your department. You have received a phone call from an angry patient. The patient stated that he presented to ED with ankle pain and did not have his pain managed adequately. He says he was told to go home and take paracetamol and that “he only had a sprain”. Subsequently, he has been to see his GP and has been told that he has a fracture that requires an\n• peration.\nOn reviewing the case you note the x-ray from 4 days prior had shown an obvious fracture. The formal report describes a Weber B fracture of the fibula and recommends urgent orthopaedic review. There is no evidence from the notes that the patient was unco-operative with assessment or management.","parts":[{"id":"a","label":"Part A","prompt":"In the table below, list one factor in each of the categories given that may have contributed to this situation, and two strategies you may employ to address each factor you have listed. (9 marks)"},{"id":"b","label":"Part B","prompt":"List 4 actions you would take to deal with this situation."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>SYSTEM</td><td>Inadequate staffing at senior</td><td>Review adequacy of staff mix to ensure</td></tr><tr><td>LEVEL</td><td>level</td><td>adequate senior supervision</td></tr><tr><td colspan=\"3\">Inadequate rostering within</td></tr><tr><td colspan=\"3\">department areas</td></tr><tr><td colspan=\"3\">Ensure senior staff rostered to/responsible for</td></tr><tr><td colspan=\"3\">ambulatory care area</td></tr><tr><td>PROCESS</td><td>Xray reporting delays</td><td>Ask radiology to look at reporting times</td></tr><tr><td>LEVEL</td><td>No notification of abnormal</td><td>Single point contact (ED Consultant) for</td></tr><tr><td>imaging to clinical staff</td><td>abnormal imaging</td><td></td></tr><tr><td colspan=\"3\">Lack of senior review of</td></tr><tr><td colspan=\"3\">Mandate all imaging/patients of junior staff</td></tr><tr><td colspan=\"3\">patient/imaging  prior to</td></tr><tr><td colspan=\"3\">discussed and reviewed prior to discharge at</td></tr><tr><td colspan=\"3\">discharge</td></tr><tr><td colspan=\"3\">reg/consultant level.</td></tr><tr><td>INDIVIDUAL</td><td>Lack of understanding/skill in</td><td>Look at resident education program – common</td></tr><tr><td>LEVEL</td><td>xray interpretation</td><td>missed injuries</td></tr><tr><td colspan=\"3\">Poor patient communication</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">consider workshops on communication skills</div><div class=\"answer-line\">2. Apologise and acknowledge inadequacy of initial care</div><div class=\"answer-line\">Expedite rapid  return and assessment – advise patient to return to ED; arrange</div><div class=\"answer-line\">senior review on arrival</div><div class=\"answer-line\">Provide necessary clinical care – re-image/reduce/immobilise and analgesia</div><div class=\"answer-line\">Pledge to investigate and feedback</div><div class=\"answer-line\">Document all interactions</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 30 year old woman has been brought to the ED with dyspnoea.\nShe is receiving chemotherapy for treatment of melanoma. Her chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 2 relevant positive radiological abnormalities.\n(2 marks)"},{"id":"b","label":"Part B","prompt":"List 2 relevant negative findings.\n(2 marks)"},{"id":"c","label":"Part C","prompt":"List 4 potential infectious causes of the x-ray findings. Ensure each cause is from a\ndifferent microbiological class. (4 marks)"},{"id":"d","label":"Part D","prompt":"List 4 potential non-infectious causes of the x-ray findings."}],"propPages":["asset:imgee94242f9c1539dde1"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bilateral symmetrical infiltrates</div><div class=\"answer-line\">Alveolar infiltrates with some confluent/round lesions</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">No effusions</div><div class=\"answer-line\">Normal heart size</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Mycoplasma pneumoniae (many others)</div><div class=\"answer-line\">Mycobacterium tuberculosis</div><div class=\"answer-line\">Aspergillus</div><div class=\"answer-line\">Influenza</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pulmonary haemorrhage eg Wegener’s granulomatosis</div><div class=\"answer-line\">Lymphangitis carcinomatosis</div><div class=\"answer-line\">Pulmonary oedema</div><div class=\"answer-line\">Leucostasis eg acute leukaemia</div><div class=\"answer-line\">Alveolar proteinosis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 3 year old boy has presented with a rash. The junior medical officer who has seen the patient is concerned about the possibility of Kawasaki disease. A photograph of the rash is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 5 other clinical features (apart from rash) which would support a diagnosis of\nKawasaki disease. (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 differential diagnoses for this patient’s rash.\n(5 marks)"},{"id":"c","label":"Part C","prompt":"List 4 complications of Kawasaki disease.\n(4 marks)"}],"propPages":["asset:img9cbbb5cb2ab790d666"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/14</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">–  Fever for &gt; 5 days</td></tr><tr><td>ii.</td><td>– Bilateral conjunctival injection</td></tr><tr><td>iii.</td><td>– Mucous membrane changes (cracked lips, red pharynx, ‘strawberry’ tongue)</td></tr><tr><td>iv.</td><td>– Extremity changes: erythema palms/soles, edema hands/feet, desquamation</td></tr><tr><td>v.</td><td>– Cervical lymphadenopathy</td></tr><tr><td colspan=\"2\">2.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">– Measles</td></tr><tr><td>ii.</td><td>– Other Viral exanthem</td></tr><tr><td>iii.</td><td>– Staph infection (Toxic shock syndrome, Scalded skin syndrome)</td></tr><tr><td>iv.</td><td>– Strep infection (Toxic shock syndrome, Scarlet fever)</td></tr><tr><td>v.</td><td>– Erythema Multiforme</td></tr><tr><td>vi.</td><td>- Stevens-Johnsons</td></tr><tr><td>vii.</td><td>– Drug reaction</td></tr><tr><td>viii.</td><td>– EBV</td></tr><tr><td>ix.</td><td>- Leptospirosis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>– Coronary artery aneurysms</td></tr><tr><td>ii.</td><td>– Myocardial infarction</td></tr><tr><td>iii.</td><td>– Arrhythmias</td></tr><tr><td>iv.</td><td>– Cardiac failure/ impaired LV function</td></tr><tr><td>v.</td><td>– Myocarditis</td></tr><tr><td>vi.</td><td>– Pericarditis</td></tr><tr><td>vii.</td><td>– Pericardial effusions</td></tr><tr><td>viii.</td><td>– Valve dysfunction</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 54 year old man has presented to the ED with epigastric abdominal pain and fevers for the last 24 hours. Some of his blood results are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Provide an explanation for the following results:\nProt 88, Alb 32, Glob 55\n(1 mark)\nBili 88, Bili (conj) 62\n(1 mark)\nALP 540, GGT 503, ALT 190, AST 181\n(1 mark)"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (2 marks) You have decided to perform further radiological investigation in to the cause of the abnormalities shown."},{"id":"c","label":"Part C","prompt":"List 2 pros and 2 cons for each of the investigations listed.\n(8 marks) Pros Cons CT scan USS scan"}],"propPages":["asset:imgba19ba1b37e93b4487"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Due to inflammatory state/sepsis with raised globulins to fight infection at the expense of</div><div class=\"answer-line\">albumin production (negative acute phase reaction)</div><div class=\"answer-line\">Jaundice due to biliary obstruction</div><div class=\"answer-line\">Ductal enzymes higher than hepatocellular c/w biliary obstruction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Cholangitis with biliary obstruction</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Radiol</td><td>Advantages Disadvantages</td></tr><tr><td>Ix</td><td></td></tr><tr><td>•</td><td>Not as sensitive/specific for</td></tr><tr><td>•</td><td>Specific and sensitive for CBD gallstones as US</td></tr><tr><td>CT</td><td>dilation/ obstruction/ cause/level • Contrast</td></tr><tr><td>(cholangitis)</td><td>• Radiation</td></tr><tr><td>•</td><td>Good sensitivity for cholecystitis (wall</td></tr><tr><td>thickening, peri-cholecystic fluid</td><td>Must mention 1st point to get &gt; 1</td></tr><tr><td>•</td><td>Assesses pancreas/head of pancreas mark</td></tr><tr><td>well (if obstruction)</td><td></td></tr><tr><td>•</td><td>Identifies other pathology (intra</td></tr><tr><td>abdominal, renal, pneumonia)</td><td></td></tr><tr><td>Must 1st point to get &gt; 1 for this box</td><td></td></tr><tr><td>•</td><td>Sensitive + Specific for gallstones/ • May not define level/cause of</td></tr><tr><td>USS</td><td>cholecystitis (investigation of choice) obstruction if duct distension/</td></tr><tr><td>•</td><td>Sensitive for biliary duct dilation cholangitis esp if distal</td></tr><tr><td>(cholangitis)</td><td>• Limited diagnosis other intra-</td></tr><tr><td>abdominal pathology</td><td></td></tr><tr><td>•</td><td>Operator dependent/ habitus</td></tr><tr><td>Must mention 1st point to get &gt; 1</td><td></td></tr><tr><td>mark this box</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 27 year old woman has presented with lower abdominal cramping pain. She is 29 weeks pregnant by dates.","parts":[{"id":"a","label":"Part A","prompt":"List 4 aims of your assessment. For each aim, state one supportive historical or\nexamination feature. (8 marks) Assessment Aim Supportive historical or examination feature"},{"id":"b","label":"Part B","prompt":"State 4 treatments you might use in this situation. Give the clinical indication for each\ntreatment. (8 marks) Treatment Clinical indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>12/16</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Labour established</td><td>Presence of pelvic pressure / low back pain</td></tr><tr><td>Regular contractions / strength of contractions /</td><td></td></tr><tr><td>palpable uterine activity on examination</td><td></td></tr><tr><td>Rupture membranes</td><td>Loss of fluid, blood or mucous PV – suggesting</td></tr><tr><td>PROM</td><td></td></tr><tr><td>Sterile speculum examination- state of cervix</td><td></td></tr><tr><td>(dilatation) / membranes (?ruptured)</td><td></td></tr><tr><td>Stage of labour</td><td>Cervix length/effacement, dilatation on PV</td></tr><tr><td>Foetal well-being</td><td>Foetal surveillance – FHR / CTG</td></tr><tr><td>Mother well-being</td><td>Vital signs – BP – pre-eclampsia</td></tr><tr><td>Risk factors for pre-term labour</td><td>Previous pre-term labour - details</td></tr><tr><td>History of pregnancy thus far – assisted</td><td></td></tr><tr><td>reproduction, polyhydramnios /</td><td></td></tr><tr><td>oligohydramnios, short cervical length (risks for</td><td></td></tr><tr><td>pre-term labour)</td><td></td></tr><tr><td>Medical history – recent / current UTI (risks for</td><td></td></tr><tr><td>pre-term labour)</td><td></td></tr><tr><td>Also accept one answer that assesses for non-pregnancy causes eg appendicitis</td><td></td></tr><tr><td>2.</td><td></td></tr><tr><td>Treatment and reason for treatment</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Antenatal corticosteroids</td><td>For foetal lung maturity if gestation &lt;34/40</td></tr><tr><td>Betamethasone 11.4mg IMI</td><td></td></tr><tr><td>Nifedipine 20mg po</td><td>Tocolysis in pre-term labour where foetus at</td></tr><tr><td>risk due to prematurity</td><td></td></tr><tr><td>Magnesium sulphate</td><td>For foetal neuroprotection in pre-term babies</td></tr><tr><td>4g IV over 20min / then 1g / hour</td><td></td></tr><tr><td>IV antibiotics – ampicillin, gentamicin,</td><td>If chorio-amnionitis established</td></tr><tr><td>metronidazole</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 25 year old man has presented with severe central chest pain of 12 hours duration.\nHe has been unwell for one week with lethargy and malaise following an upper respiratory tract infection diagnosed by his GP. He has no past medical history. His ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give 2 differential diagnoses. For each, list 2 supportive ECG findings and 1 supportive\nechocardiographic finding. (8 marks) Differential diagnosis Supportive ECG findings Supportive echo finding"}],"propPages":["asset:img4b18672bb94123a57e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/8</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Acute STEMI</td><td></td></tr><tr><td>-</td><td>Presence of ST elevation with reciprocal depression in I and aVL</td></tr><tr><td>-</td><td>Q waves in V1 and V2</td></tr><tr><td>-</td><td>STE III &gt; II</td></tr><tr><td>-</td><td>RWMA on echo would support STEMI</td></tr><tr><td>Acute pericarditis / myocarditis</td><td></td></tr><tr><td>-</td><td>Widespread STE not conforming to one anatomical region</td></tr><tr><td>-</td><td>Saddle shaped STE</td></tr><tr><td>-</td><td>No RWMA, presence of pericardial effusion</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 42 year old man has presented to the ED after a large aspirin overdose.","parts":[{"id":"a","label":"Part A","prompt":"List 5 clinical features of salicylate toxicity.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"Complete the following table regarding potential management steps for this patient. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>5/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Initial hyperventilation</div><div class=\"answer-line\">Nausea</div><div class=\"answer-line\">Vomiting</div><div class=\"answer-line\">Tinnitus</div><div class=\"answer-line\">Dehydration</div><div class=\"answer-line\">Pyrexia</div><div class=\"answer-line\">Confusion</div><div class=\"answer-line\">Pulmonary oedema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">2.</td></tr><tr><td>Indication(s)</td><td>Dosing instructions</td><td></td></tr><tr><td>1.<strong> </strong>Decontamination</td><td>Ingestion &gt;150mg/kg within</td><td>50g oral charcoal (+/-</td></tr><tr><td>last 6hrs</td><td>repeat doses in large</td><td></td></tr><tr><td colspan=\"3\">ingestions)</td></tr><tr><td>2.<strong> </strong>Urinary alkalinisation</td><td>Symptomatic patient</td><td>1-2mmol/kg bolus Na</td></tr><tr><td colspan=\"3\">HCO3</td></tr><tr><td colspan=\"3\">Then 25mmol/hr NaHCO3</td></tr><tr><td colspan=\"3\">Aim urinary pH &gt;7.5</td></tr><tr><td colspan=\"3\">(Need 2/3)</td></tr><tr><td>3.<strong> </strong>Haemodialysis</td><td>In severe toxicity:</td><td></td></tr><tr><td>•</td><td>Pre-existing</td><td></td></tr><tr><td colspan=\"3\">renal/cardiac failure</td></tr><tr><td colspan=\"3\">precluding urinary</td></tr><tr><td colspan=\"3\">alkalinisation</td></tr><tr><td>•</td><td>Pulmonary oedema</td><td></td></tr><tr><td>•</td><td>Severe acidosis</td><td></td></tr><tr><td>•</td><td>Elevated salicylate</td><td></td></tr><tr><td colspan=\"3\">level &gt; 700mg/L or</td></tr><tr><td colspan=\"3\">5.1 mmol/L</td></tr><tr><td colspan=\"3\">(Need 2/4)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"An 18 year old man has been brought to the ED following a motorbike accident. He rode in to fencing wire at approximately 60km/hr. He has sustained a closed injury to the anterior of his neck where he struck the wire. There are no other injuries on assessment.\nHis vital signs are:\n\nGCS\nPulse 100 /min\n\nBP\n120/75 mmHg","parts":[{"id":"a","label":"Part A","prompt":"List 4 features on examination that would suggest a significant laryngeal injury.\n(4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 features on examination that would suggest a significant vascular injury.\n(4 marks)"},{"id":"c","label":"Part C","prompt":"List 2 investigations you could arrange to assess this injury.\n(2 marks) Based on your assessment, you have decided that the patient needs definitive airway management."},{"id":"d","label":"Part D","prompt":"State 2 major concerns you would have in securing this patient’s airway via a standard\nrapid sequence induction (RSI) with direct laryngoscopy in the ED. (2 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________"},{"id":"e","label":"Part E","prompt":"List 4 indications for immediate airway management in the ED.\n(4 marks) The patient requires immediate airway management in the ED."},{"id":"f","label":"Part F","prompt":"State 4 modifications to a standard RSI you would use in this patient. (4 marks)\n1)________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>15/20</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hoarse voice / change in voice</div><div class=\"answer-line\">stridor</div><div class=\"answer-line\">Pain on swallowing</div><div class=\"answer-line\">Haemoptysis</div><div class=\"answer-line\">Subcutaneous emphysema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">expanding haematoma</div><div class=\"answer-line\">Carotid bruits</div><div class=\"answer-line\">Focal neurological signs</div><div class=\"answer-line\">Horner’s syndrome</div><div class=\"answer-line\">Decreased consciousness</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">CTA neck</div><div class=\"answer-line\">Fibre-optic nasendoscopy</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">In ability to intubate - due to loss of usual landmarks / changes to anatomy</div><div class=\"answer-line\">Conversion of partial to complete laryngo-tracheal disruption by blind passage of ETT and</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Arrest</div><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Tiring</div><div class=\"answer-line\">Loss consciousness</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Pre-oxygenate sitting up</div><div class=\"answer-line\">Have surgical airway kit ready</div><div class=\"answer-line\">Have a dedicated person for surgical airway eg surgeon</div><div class=\"answer-line\">Use of video laryngoscope</div><div class=\"answer-line\">Would accept avoidance of paralysis as well</div><div class=\"answer-line\">Several other possibilities</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A seven year old girl has presented with a 48 hour history of fever and a swollen right eye. There is no history of trauma. Her clinical photograph is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give the most likely diagnosis. (1 mark)"},{"id":"b","label":"Part B","prompt":"List the 3 most common microbiological causes of this problem.\n(3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 potential complications of this problem. For each, state 2 examination findings that would support its presence. (9 marks) Complication Supportive examination findings"}],"propPages":["asset:img1d853024a2884fcf52"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Peri-orbital cellulitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Streptococcus</div><div class=\"answer-line\">Haemophilus</div><div class=\"answer-line\">Staphylococcus</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Orbital cellulitis / retro-orbital- pain on eye movement, opthalmoplegia, loss of visual acuity,</td><td>proptosis</td></tr><tr><td>Cavernous sinus thrombosis- headache, Ptosis, cranial nerve (3-6) palsy</td><td>Meningoencephalitis- meningism, headache, confusion, ALOC, seizures</td></tr><tr><td>Bacteraemia/septicemeia- high grade fever, tachycardia, hypotension.</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 56 year old man has presented to the ED with abdominal pain for the last 24 hours.\nHe has end-stage renal failure managed with peritoneal dialysis. Your junior medical officer is concerned that he might have peritoneal dialysis related peritonitis.","parts":[{"id":"a","label":"Part A","prompt":"State the assessment findings that would be consistent with this diagnosis. (3 marks) Assessment finding History Examination Peritoneal fluid white blood cell count"},{"id":"b","label":"Part B","prompt":"List 4 features of your history and/or examination that would suggest a surgical cause for this patient’s abdominal pain. (4 marks) 1)________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ The patient has peritoneal dialysis related peritonitis.\nHis vital signs are normal."},{"id":"c","label":"Part C","prompt":"State 3 treatments you would use.\n(3 marks) 1)________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">History – gradual onset, constant pain, cloudy dialysate bags</div><div class=\"answer-line\">Examination – generalized tenderness, signs of peritonism eg percussion tenderness, fever</div><div class=\"answer-line\">Fluid WBC - &gt;100 *10^6/L, &gt;50% neutrophils</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Focal tenderness</div><div class=\"answer-line\">Colicky pain</div><div class=\"answer-line\">Sudden onset pain</div><div class=\"answer-line\">Other features eg PR bleeding</div><div class=\"answer-line\">Many others will be OK</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IP cephazolin 15mg/kg</div><div class=\"answer-line\">IP gentamicin 0.6mg/kg up to 50mg</div><div class=\"answer-line\">Analgesia – IV fentanyl 25mcg boluses</div><div class=\"answer-line\">IP vancomycin 30mg/kg up to 2g if MRSA</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 16 year old female has presented to the ED with her boyfriend. She has complained of lower abdominal pain for several days. Her past medical history includes intravenous amphetamine abuse. Your assessment is consistent with pelvic inflammatory disease.","parts":[{"id":"a","label":"Part A","prompt":"List 4 investigations you might perform. Include the justification for each.\n(4 marks) Investigation Justification You have decided that the patient requires admission for further management of severe pelvic inflammatory disease.\nHer vital signs are:\n\nGCS\nPulse 105 /min\n\nBP\n115/75 mmHg\n\nTemp\ndegrees"},{"id":"b","label":"Part B","prompt":"List the components of your antibiotic regime. (3 marks) The patient has become agitated after an argument with her mother who has recently arrived to the ED. She demands to leave with her boyfriend."},{"id":"c","label":"Part C","prompt":"List 3 elements of competence that you will need to assess in order to determine if you\nwill allow the patient to leave. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>BHCG</td><td>Exclude pregnancy as complicating factor / septic</td></tr><tr><td>miscarriage</td><td></td></tr><tr><td>Endocervical swabs</td><td>PID- N. gonorrhoeae and C. Trachomatis</td></tr><tr><td>Urine PCR first pass</td><td>As above</td></tr><tr><td>US- exp transvaginal</td><td>Tubo-ovarian abscess</td></tr><tr><td>Extended serology</td><td>HIV, hepatitis, syphilis as con-infection sexually</td></tr><tr><td>transmissible</td><td></td></tr><tr><td>LFTs</td><td>Fitz-Hugh-Curtis syndrome</td></tr><tr><td>CT Abdomen not acceptable, non-specific tests or examinations not acceptable.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ceftriaxone 2g od IV</div><div class=\"answer-line\">Azithromycin 500mg od IV</div><div class=\"answer-line\">Metronidazole 500mg bd IV</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Choice- the ability to maintain and communicate a choice.</div><div class=\"answer-line\">2. Comprehension- the ability to understand the relevant information.</div><div class=\"answer-line\">3. Belief- the ability to appreciate the situation and its consequences</div><div class=\"answer-line\">4. Weighing- the ability to weight the information in a rational fashion.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
